import { get, getSecret } from '@clevercloud/client/esm/api/v2/oauth-consumer.js';
import { z } from 'zod';
import { defineCommand } from '../../lib/define-command.js';
import { defineOption } from '../../lib/define-option.js';
import { Logger } from '../../logger.js';
import { getId as getOrgaId } from '../../models/organisation.js';
import { sendToApi } from '../../models/send-to-api.js';
import { humanJsonOutputFormatOption, orgaIdOrNameOption } from '../global.options.js';
import { consumerKeyArg } from './oauth-consumers.args.js';

export const oauthConsumersGetCommand = defineCommand({
  description: 'Get information about an OAuth consumer',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    withSecret: defineOption({
      name: 'with-secret',
      schema: z.boolean().default(false),
      description: 'Also display the consumer secret',
    }),
    format: humanJsonOutputFormatOption,
  },
  args: [consumerKeyArg],
  async handler(options, key) {
    const { org, withSecret, format } = options;

    const id = await getOrgaId(org);
    const consumer = await get({ id, key }).then(sendToApi);
    const secret = withSecret ? await getSecret({ id, key }).then(sendToApi) : null;
    const secretValue = secret != null && typeof secret === 'object' ? secret.secret : secret;

    if (format === 'json') {
      Logger.printJson(withSecret ? { ...consumer, secret: secretValue } : consumer);
      return;
    }

    Logger.println(`Name: ${consumer.name}`);
    Logger.println(`Key: ${consumer.key}`);
    if (withSecret) {
      Logger.println(`Secret: ${secretValue}`);
    }
    Logger.println(`Description: ${consumer.description ?? ''}`);
    Logger.println(`URL: ${consumer.url ?? ''}`);
    Logger.println(`Base URL: ${consumer.baseUrl ?? ''}`);
    Logger.println(`Picture: ${consumer.picture ?? ''}`);
    const rights = Object.entries(consumer.rights ?? {})
      .filter(([, granted]) => granted)
      .map(([right]) => right);
    Logger.println(`Rights: ${rights.join(', ')}`);
  },
});
